Here is the commit message:
spi: stm32-qspi: Remove unused qspi field of struct
 stm32_qspi_flash

Remove struct stm32_qspi_flash's field qspi which is not used.

Fixes: c530cd1d9d5e ("spi: spi-mem: add stm32 qspi controller")
Signed-off-by: Patrice Chotard <patrice.chotard@foss.st.com>
Link: https://lore.kernel.org/r/20210615090115.30702-1-patrice.chotard@foss.st.com
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The root cause of the bug was the presence of an unused field `qspi` in the `struct stm32_qspi_flash`, which could lead to confusion and potential misuse in the codebase. Since the field was not utilized, it contributed to unnecessary complexity and could mislead developers into thinking it had a purpose, potentially resulting in incorrect assumptions about the structure's functionality.

Here is the patch:

 struct stm32_qspi_flash {
-	struct stm32_qspi *qspi;
 	u32 cs;
 	u32 presc;

 static int stm32_qspi_setup(struct spi_device *spi)
 {
 	struct spi_controller *ctrl = spi->master;
 	struct stm32_qspi *qspi = spi_controller_get_devdata(ctrl);
 	struct stm32_qspi_flash *flash;
 	u32 presc;
 	int ret;

 	if (ctrl->busy)
 		return -EBUSY;

 	if (!spi->max_speed_hz)
 		return -EINVAL;

 	ret = pm_runtime_get_sync(qspi->dev);
 	if (ret < 0) {
 		pm_runtime_put_noidle(qspi->dev);
 		return ret;
 	}

 	presc = DIV_ROUND_UP(qspi->clk_rate, spi->max_speed_hz) - 1;

 	flash = &qspi->flash[spi->chip_select];
-	flash->qspi = qspi;
 	flash->cs = spi->chip_select;
 	flash->presc = presc;

 	mutex_lock(&qspi->lock);
 	qspi->cr_reg = CR_APMS | 3 << CR_FTHRES_SHIFT | CR_SSHIFT | CR_EN;
 	writel_relaxed(qspi->cr_reg, qspi->io_base + QSPI_CR);

 	/* set dcr fsize to max address */
 	qspi->dcr_reg = DCR_FSIZE_MASK;
 	writel_relaxed(qspi->dcr_reg, qspi->io_base + QSPI_DCR);
 	mutex_unlock(&qspi->lock);

 	pm_runtime_mark_last_busy(qspi->dev);
 	pm_runtime_put_autosuspend(qspi->dev);

 	return 0;
 }



